#include "ui/localization.hpp"
#include <cassert>
int main(){using namespace pastit;assert(tr(UiLanguage::English,UiTextKey::Settings)=="Settings");assert(tr(UiLanguage::SimplifiedChinese,UiTextKey::Settings)=="设置");assert(tr(UiLanguage::SimplifiedChinese,UiTextKey::KeyboardHint).find("选择")!=std::string::npos);assert(tr(UiLanguage::SimplifiedChinese,UiTextKey::Zoom)=="缩放");assert(tr(UiLanguage::SimplifiedChinese,UiTextKey::DjevTestSucceeded).find("成功")!=std::string::npos);assert(tr(UiLanguage::SimplifiedChinese,UiTextKey::GeneralLlmTestFailed).find("失败")!=std::string::npos);assert(tr(UiLanguage::SimplifiedChinese,UiTextKey::Saved)=="已保存");
const UiTextKey added[]={UiTextKey::General,UiTextKey::KeepLatest10,UiTextKey::DeleteAllHistory,UiTextKey::RefreshModels,UiTextKey::ModelList,UiTextKey::ModelListFailed,UiTextKey::HistoryPruned,UiTextKey::HistoryDeleted,UiTextKey::CopyTemporaryPath,UiTextKey::ClipboardHistory,UiTextKey::Preview,UiTextKey::Size,UiTextKey::Captured,UiTextKey::Details,UiTextKey::View,UiTextKey::Edit,UiTextKey::Close,UiTextKey::MimeTypes,UiTextKey::MissingData,UiTextKey::PromptActions,UiTextKey::ConfigureGeneralLlm,UiTextKey::BuiltIn,UiTextKey::Custom,UiTextKey::Browse,UiTextKey::Destination,UiTextKey::Filename,UiTextKey::OutputPath,UiTextKey::Confirm,UiTextKey::InvalidPath,UiTextKey::InvalidFilename,UiTextKey::SourceParent,UiTextKey::FocusedDirectory,UiTextKey::ManualDestination,UiTextKey::DeleteTemplateText,UiTextKey::DuplicateTemplateText,UiTextKey::UseAsDestination,UiTextKey::OpenParent,UiTextKey::Use,UiTextKey::Seen,UiTextKey::Parent,UiTextKey::Reference,UiTextKey::CopyHereAction,UiTextKey::MoveHereAction,UiTextKey::ConfirmFileOperation};for(const auto key:added){assert(!tr(UiLanguage::English,key).empty());assert(!tr(UiLanguage::SimplifiedChinese,key).empty());}
assert(resolve_language(UiLanguage::System,"zh_CN.UTF-8")==UiLanguage::SimplifiedChinese);assert(resolve_language(UiLanguage::System,"xx_YY")==UiLanguage::English);}
